/* ShiftSwap tokens. Components come from shadcn/ui and read these variables, so a change
   here changes every button, card and badge. */
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 40 20% 98%;
    --foreground: 222 20% 14%;
    --card: 0 0% 100%;
    --card-foreground: 222 20% 14%;
    --primary: 214 70% 34%;
    --primary-foreground: 0 0% 100%;
    --muted: 220 14% 94%;
    --muted-foreground: 220 9% 42%;
    --border: 220 13% 88%;
    --ring: 214 70% 34%;
    --radius: 0.6rem;

    /* Shift states: one color each, used by Badge and the week view */
    --shift-mine: 214 70% 34%;
    --shift-open: 152 45% 32%;
    --shift-pending: 38 92% 40%;
    --shift-declined: 0 65% 45%;
    --shift-conflict: 0 65% 45%;

    --font-sans: "Inter", system-ui, sans-serif;
    --text-xs: 0.75rem;
    --text-sm: 0.875rem;
    --text-base: 1rem;
    --text-lg: 1.125rem;
    --text-xl: 1.375rem;
  }

  .dark {
    --background: 222 20% 9%;
    --foreground: 40 20% 96%;
    --card: 222 18% 13%;
    --card-foreground: 40 20% 96%;
    --primary: 214 80% 66%;
    --primary-foreground: 222 20% 9%;
    --muted: 222 14% 18%;
    --muted-foreground: 220 9% 66%;
    --border: 222 12% 24%;
    --shift-mine: 214 80% 66%;
    --shift-open: 152 45% 56%;
    --shift-pending: 38 92% 60%;
    --shift-declined: 0 70% 64%;
    --shift-conflict: 0 70% 64%;
  }

  body {
    @apply bg-background text-foreground;
    font-family: var(--font-sans);
    font-size: var(--text-base);
  }
}

/* Week view grid: seven columns on wide screens, time down the side. */
.week-grid {
  display: grid;
  grid-template-columns: 4rem repeat(7, minmax(0, 1fr));
  gap: 1px;
  background: hsl(var(--border));
}
.week-grid > div { background: hsl(var(--card)); min-height: 2.5rem; }

.shift-block {
  border-radius: calc(var(--radius) - 2px);
  padding: 0.25rem 0.5rem;
  font-size: var(--text-sm);
  border: 1px solid transparent;
}
.shift-block[data-state="mine"] { background: hsl(var(--shift-mine)); color: hsl(var(--primary-foreground)); }
.shift-block[data-state="open"] { border-color: hsl(var(--shift-open)); color: hsl(var(--shift-open)); }
.shift-block[data-state="pending"] { border-style: dashed; border-color: hsl(var(--shift-pending)); }
.shift-block[data-state="conflict"] { border-color: hsl(var(--shift-conflict)); opacity: .7; }

/* Empty and error states share one layout: icon, one line, one action. */
.state-panel {
  display: grid;
  justify-items: center;
  gap: 0.75rem;
  padding: 3rem 1rem;
  color: hsl(var(--muted-foreground));
  text-align: center;
}
.state-panel h2 { font-size: var(--text-lg); color: hsl(var(--foreground)); }

