import { createClient } from "@/lib/supabase/server";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/states/empty-state";
import { ErrorState } from "@/components/states/error-state";
import { ShiftCard } from "@/components/shift-card";
import { SwapCard } from "@/components/swap-card";
import { startOfWeek, endOfWeek } from "@/lib/dates";

// The shift board: this week's open shifts, my shifts, and swaps waiting on me.
// Row-level security decides what comes back, so these queries never filter by user.
export default async function BoardPage() {
  const supabase = await createClient();
  const from = startOfWeek(new Date());
  const to = endOfWeek(new Date());

  const [open, mine, swaps] = await Promise.all([
    supabase.from("shifts").select("*").eq("status", "open").gte("starts_at", from).lte("starts_at", to).order("starts_at"),
    supabase.from("shifts").select("*").eq("is_mine", true).gte("starts_at", from).lte("starts_at", to).order("starts_at"),
    supabase.from("swap_requests").select("*, shift:shifts(*)").in("status", ["pending", "declined"]).order("created_at"),
  ]);

  if (open.error || mine.error || swaps.error) {
    return (
      <ErrorState
        title="Shifts did not load"
        detail="ShiftSwap could not reach the schedule. Your shifts are safe."
        action={{ label: "Retry", href: "/board" }}
      />
    );
  }

  return (
    <div className="grid gap-6 lg:grid-cols-3">
      <Card>
        <CardHeader><CardTitle>Open shifts this week</CardTitle></CardHeader>
        <CardContent className="grid gap-2">
          {open.data.length === 0 ? (
            <EmptyState title="No open shifts" detail="When a coworker posts a shift, it shows up here." />
          ) : (
            open.data.map((s) => <ShiftCard key={s.id} shift={s} action="pick-up" />)
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle>My shifts</CardTitle></CardHeader>
        <CardContent className="grid gap-2">
          {mine.data.length === 0 ? (
            <EmptyState
              title="No shifts this week"
              detail="Import the paper schedule to fill in your shifts."
              action={{ label: "Import a schedule photo", href: "/import" }}
            />
          ) : (
            mine.data.map((s) => <ShiftCard key={s.id} shift={s} action="post" />)
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle>Swaps</CardTitle></CardHeader>
        <CardContent className="grid gap-2">
          {swaps.data.length === 0 ? (
            <EmptyState title="No swaps in progress" detail="Swaps you post or pick up wait here for the manager." />
          ) : (
            swaps.data.map((w) => <SwapCard key={w.id} swap={w} />)
          )}
