// Turns the times written on the paper schedule into 24-hour start and end times.
// The circulation desk sheet uses forms like "7a-11", "1:30-5p", "11-3" and "12-4:30".

export type RawCell = { person: string; day: string; text: string };
export type Shift = { person: string; day: string; start: string; end: string };

const RANGE = /^(\d{1,2})(?::(\d{2}))?\s*([ap])?\s*[-\u2013to]+\s*(\d{1,2})(?::(\d{2}))?\s*([ap])?$/i;

function to24(h: number, m: number, ap: string | undefined, fallbackPm: boolean): string {
  let hour = h;
  const pm = ap ? ap.toLowerCase() === "p" : fallbackPm;
  if (pm && hour < 12) hour += 12;
  if (!pm && hour === 12) hour = 0;
  return `${String(hour).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

// A cell can hold two blocks ("7a-11, 1-5p"), which become two shifts.
export function splitBlocks(text: string): string[] {
  return text
    .split(/[,;\n]/)
    .map((t) => t.trim())
    .filter((t) => t && !/^(x+|off|-+)$/i.test(t));
}

export function parseRange(text: string): { start: string; end: string } | null {
  const m = text.replace(/\s+/g, " ").match(RANGE);
  if (!m) return null;
  const [, h1, m1, ap1, h2, m2, ap2] = m;
  const startH = Number(h1);
  const endH = Number(h2);
  // The desk opens at 7 AM and closes at 11 PM, so an hour of 1 to 6 without a/p is PM.
  const start = to24(startH, Number(m1 ?? 0), ap1, startH >= 1 && startH <= 6);
  const end = to24(endH, Number(m2 ?? 0), ap2 ?? (endH <= startH ? "p" : ap1), endH >= 1 && endH <= 6);
  if (end <= start) return null;
  return { start, end };
}

export function normalize(cells: RawCell[]): { shifts: Shift[]; skipped: { cell: RawCell; reason: string }[] } {
  const shifts: Shift[] = [];
  const skipped: { cell: RawCell; reason: string }[] = [];
  for (const cell of cells) {
    for (const block of splitBlocks(cell.text)) {
      const r = parseRange(block);
      if (r) shifts.push({ person: cell.person, day: cell.day, ...r });
      else skipped.push({ cell, reason: `could not read "${block}" as a time range` });
    }
  }
  return { shifts, skipped };
}

