// The draft a schedule photo becomes. Nothing here touches the database: the student edits
// the draft, and only Save writes the shifts. Every change is pushed onto a history stack
// so Undo can restore it.

import type { Shift } from "./normalize";

export type DraftRow = Shift & {
  id: string;
  location: string;
  confidence: "high" | "low";
  removed?: boolean;
};

export type Draft = {
  week: string; // Monday of the week printed in the schedule header, YYYY-MM-DD
  rows: DraftRow[];
  past: DraftRow[][];
  future: DraftRow[][];
};

export function createDraft(week: string, rows: DraftRow[]): Draft {
  return { week, rows, past: [], future: [] };
}

function commit(d: Draft, rows: DraftRow[]): Draft {
  return { ...d, rows, past: [...d.past, d.rows], future: [] };
}

export function editRow(d: Draft, id: string, patch: Partial<DraftRow>): Draft {
  return commit(d, d.rows.map((r) => (r.id === id ? { ...r, ...patch, confidence: "high" } : r)));
}

export function removeRow(d: Draft, id: string): Draft {
  return commit(d, d.rows.map((r) => (r.id === id ? { ...r, removed: true } : r)));
}

export function undo(d: Draft): Draft {
  if (d.past.length === 0) return d;
  const prev = d.past[d.past.length - 1];
  return { ...d, rows: prev, past: d.past.slice(0, -1), future: [d.rows, ...d.future] };
}

export function redo(d: Draft): Draft {
  if (d.future.length === 0) return d;
  const [next, ...rest] = d.future;
  return { ...d, rows: next, past: [...d.past, d.rows], future: rest };
}

// The key that makes a shift unique. A re-scan updates a shift with the same key instead
// of inserting it again (added Oct 10, after a re-scan double-booked nine shifts).
export function shiftKey(r: Pick<DraftRow, "person" | "day" | "start" | "end" | "location">): string {
  return [r.person.toLowerCase(), r.day, r.start, r.end, r.location].join("|");
}

// Rows to save: removed rows are left out, and two rows with the same key become one.
export function rowsToSave(d: Draft): DraftRow[] {
  const seen = new Map<string, DraftRow>();
  for (const r of d.rows) {
    if (r.removed) continue;
    seen.set(shiftKey(r), r);
  }
  return [...seen.values()];
}

export function lowConfidenceCount(d: Draft): number {
  return d.rows.filter((r) => !r.removed && r.confidence === "low").length;
}

