import { describe, expect, it } from "vitest";
import { parseRange, splitBlocks, normalize } from "@/lib/schedule-photo/normalize";
import { createDraft, editRow, removeRow, undo, redo, rowsToSave } from "@/lib/schedule-photo/draft";

describe("parseRange", () => {
  it("reads the forms used on the desk schedule", () => {
    expect(parseRange("7a-11")).toEqual({ start: "07:00", end: "11:00" });
    expect(parseRange("1:30-5p")).toEqual({ start: "13:30", end: "17:00" });
    expect(parseRange("11-3")).toEqual({ start: "11:00", end: "15:00" });
    expect(parseRange("12-4:30")).toEqual({ start: "12:00", end: "16:30" });
  });

  it("returns null for text that is not a time range", () => {
    expect(parseRange("call me")).toBeNull();
    expect(parseRange("5-5")).toBeNull();
  });
});

describe("splitBlocks", () => {
  it("splits a cell with two blocks and skips crossed-out cells", () => {
    expect(splitBlocks("7a-11, 1-5p")).toEqual(["7a-11", "1-5p"]);
    expect(splitBlocks("xx")).toEqual([]);
    expect(splitBlocks("OFF")).toEqual([]);
  });
});

describe("normalize", () => {
  it("records what it could not read instead of dropping it", () => {
    const { shifts, skipped } = normalize([
      { person: "A", day: "Mon", text: "7a-11" },
      { person: "B", day: "Mon", text: "see me" },
    ]);
    expect(shifts).toHaveLength(1);
    expect(skipped[0].reason).toContain("see me");
  });
});

const row = (id: string, start = "07:00") => ({
  id, person: "A", day: "Mon", start, end: "11:00", location: "Circulation", confidence: "high" as const,
});

describe("draft undo", () => {
  it("undoes an edit and redoes it", () => {
    let d = createDraft("2026-10-05", [row("1")]);
    d = editRow(d, "1", { start: "08:00" });
    expect(d.rows[0].start).toBe("08:00");
    d = undo(d);
    expect(d.rows[0].start).toBe("07:00");
    d = redo(d);
    expect(d.rows[0].start).toBe("08:00");
  });

  it("undoes a removed row", () => {
    let d = createDraft("2026-10-05", [row("1")]);
    d = removeRow(d, "1");
    expect(rowsToSave(d)).toHaveLength(0);
    d = undo(d);
    expect(rowsToSave(d)).toHaveLength(1);
  });
});

describe("re-scan", () => {
  it("never saves the same shift twice", () => {
    const d = createDraft("2026-10-05", [row("1"), row("2")]);
    expect(rowsToSave(d)).toHaveLength(1);
  });
});

