// Finds the schedule grid in the vision model's output: days across the top, names down
// the side. The model returns cells with a row label, a column label and the text in the cell.

import type { RawCell } from "./normalize";

const DAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"];

export type ModelCell = { row: string; column: string; text: string };

export function dayFromColumn(column: string): string | null {
  const c = column.trim().toLowerCase().slice(0, 3);
  const i = DAYS.indexOf(c);
  return i === -1 ? null : DAYS[i];
}

// Names are matched to the roster by first name and last initial, the way the desk
// manager writes them on the sheet.
export function matchPerson(label: string, roster: { id: string; first: string; last: string }[]): string | null {
  const [first, last = ""] = label.trim().split(/\s+/);
  const hits = roster.filter(
    (p) =>
      p.first.toLowerCase() === first.toLowerCase() &&
      (!last || p.last.toLowerCase().startsWith(last.replace(".", "").toLowerCase())),
  );
  return hits.length === 1 ? hits[0].id : null; // an ambiguous name matches nobody
}

export function toCells(cells: ModelCell[], roster: { id: string; first: string; last: string }[]) {
  const out: RawCell[] = [];
  const skipped: { cell: ModelCell; reason: string }[] = [];
  for (const cell of cells) {
    const day = dayFromColumn(cell.column);
    const person = matchPerson(cell.row, roster);
    if (!day) skipped.push({ cell, reason: `column "${cell.column}" is not a day` });
    else if (!person) skipped.push({ cell, reason: `no single roster match for "${cell.row}"` });
    else if (cell.text.trim()) out.push({ person, day, text: cell.text });
  }
  return { cells: out, skipped };
}

